enum PriorityScore {
  HIGH
  LOW
}

enum TreatmentStage {
  STAGE_1
  STAGE_2
  STAGE_3
}

class Patient {
  + hasConsent : boolean
}

class Doctor {
  + isHeadDoctor : boolean
}

class Illness {
  + priorityScore : PriorityScore
}

class Diagnosis {
  + description : string
}

class Treatment {
  + stage : TreatmentStage
}

class ConsentForm {
  + signedDate : date
}

Patient "1" -- "*" Doctor : is assigned to
Patient "1" -- "*" Diagnosis : has
Patient "1" -- "*" Treatment : undergoes
Patient "1" -- "0..1" ConsentForm : signs

Doctor "1" -- "*" Diagnosis : makes
Doctor "1" -- "*" Treatment : manages
Doctor "1" -- "*" Treatment : downgrades

Diagnosis "1" -- "1" Illness : is a diagnosis of
Illness "1" -- "*" Treatment : has possible
Illness "1" -- "1" PriorityScore : has

Treatment "*" -- "1" Diagnosis : treats

@enduml

